1	//! Ear-clipping polygon triangulator.
2	//!
3	//! A `std`-only port of the `mapbox::earcut` 2.2.x algorithm: build a circular
4	//! doubly-linked list from the outer ring, splice holes in as bridges, then clip
5	//! ears one by one. When no ear can be found the algorithm escalates through
6	//! three fallbacks — filter collinear points, cure local self-intersections,
7	//! and finally split the ring on a valid diagonal — which is what makes a
8	//! self-intersecting input such as a spiral triangulable at all.
9	//!
10	//! The triangle indices are emitted in exactly the order the reference
11	//! implementation emits them; the fallback passes are order-sensitive, so the
12	//! control flow is kept structurally identical rather than idiomatically
13	//! restructured.
14	
15	pub mod geom;
16	pub mod node;
17	pub mod zorder;
18	
19	// `self::` prefix keeps the import resolvable under the 2015 edition too, so a
20	// bare `rustc test7.rs` (which defaults to 2015) builds as well as `--edition 2021`.
21	use self::node::{Node, NIL};
22	
23	/// Triangulate a polygon given as a list of rings (outer ring first, holes after)
24	/// and return a flat list of triangle vertex indices into the concatenated rings.
25	pub fn earcut(points: &[Vec<[f64; 2]>]) -> Vec<u32> {
26	    let mut earcut = Earcut::new();
27	    earcut.run(points);
28	    earcut.indices
29	}
30	
31	pub struct Earcut {
32	    pub indices: Vec<u32>,
33	    pub vertices: usize,
34	
35	    /// Arena backing the linked list; `usize` indices replace the original `Node*`.
36	    pub(crate) nodes: Vec<Node>,
37	
38	    hashing: bool,
39	    min_x: f64,
40	    max_x: f64,
41	    min_y: f64,
42	    max_y: f64,
43	    inv_size: f64,
44	}
45	
46	impl Default for Earcut {
47	    fn default() -> Self {
48	        Self::new()
49	    }
50	}
51	
52	impl Earcut {
53	    pub fn new() -> Self {
54	        Earcut {
55	            indices: Vec::new(),
56	            vertices: 0,
57	            nodes: Vec::new(),
58	            hashing: false,
59	            min_x: 0.0,
60	            max_x: 0.0,
61	            min_y: 0.0,
62	            max_y: 0.0,
63	            inv_size: 0.0,
64	        }
65	    }
66	
67	    /// Allocate a node in the arena and return its index.
68	    pub(crate) fn construct(&mut self, i: u32, x: f64, y: f64) -> usize {
69	        self.nodes.push(Node::new(i, x, y));
70	        self.nodes.len() - 1
71	    }
72	
73	    pub fn run(&mut self, points: &[Vec<[f64; 2]>]) {
74	        // reset
75	        self.indices.clear();
76	        self.vertices = 0;
77	        self.nodes.clear();
78	        self.hashing = false;
79	        self.inv_size = 0.0;
80	
81	        if points.is_empty() {
82	            return;
83	        }
84	
85	        // The z-order hash only pays off past a vertex count threshold; the loop
86	        // stops early once the budget is blown, matching the reference exactly.
87	        let mut threshold: i32 = 80;
88	        let mut len: usize = 0;
89	        let mut i = 0;
90	        while threshold >= 0 && i < points.len() {
91	            threshold -= points[i].len() as i32;
92	            len += points[i].len();
93	            i += 1;
94	        }
95	
96	        // estimate size of nodes and indices
97	        self.nodes.reserve(len * 3 / 2);
98	        self.indices.reserve(len + points[0].len());
99	
100	        let mut outer_node = self.linked_list(&points[0], true);
101	        if outer_node == NIL || self.nodes[outer_node].prev == self.nodes[outer_node].next {
102	            return;
103	        }
104	
105	        if points.len() > 1 {
106	            outer_node = self.eliminate_holes(points, outer_node);
107	        }
108	
109	        // if the shape is not too simple, we'll use z-order curve hash later;
110	        // calculate polygon bbox
111	        self.hashing = threshold < 0;
112	        if self.hashing {
113	            let mut p = self.nodes[outer_node].next;
114	            self.min_x = self.nodes[outer_node].x;
115	            self.max_x = self.min_x;
116	            self.min_y = self.nodes[outer_node].y;
117	            self.max_y = self.min_y;
118	            loop {
119	                let (x, y) = (self.nodes[p].x, self.nodes[p].y);
120	                self.min_x = self.min_x.min(x);
121	                self.min_y = self.min_y.min(y);
122	                self.max_x = self.max_x.max(x);
123	                self.max_y = self.max_y.max(y);
124	                p = self.nodes[p].next;
125	                if p == outer_node {
126	                    break;
127	                }
128	            }
129	
130	            // min_x, min_y and inv_size are later used to transform coords into
131	            // integers for z-order calculation
132	            self.inv_size = (self.max_x - self.min_x).max(self.max_y - self.min_y);
133	            self.inv_size = if self.inv_size != 0.0 {
134	                32767.0 / self.inv_size
135	            } else {
136	                0.0
137	            };
138	        }
139	
140	        self.earcut_linked(outer_node, 0);
141	    }
142	
143	    /// Create a circular doubly-linked list from polygon points in the specified
144	    /// winding order.
145	    fn linked_list(&mut self, points: &[[f64; 2]], clockwise: bool) -> usize {
146	        let mut sum = 0.0;
147	        let len = points.len();
148	        let mut last = NIL;
149	
150	        // calculate original winding order of a polygon ring
151	        let mut j = if len > 0 { len - 1 } else { 0 };
152	        for i in 0..len {
153	            let p1 = &points[i];
154	            let p2 = &points[j];
155	            let p20 = p2[0];
156	            let p10 = p1[0];
157	            let p11 = p1[1];
158	            let p21 = p2[1];
159	            sum += (p20 - p10) * (p11 + p21);
160	            j = i;
161	        }
162	
163	        // link points into circular doubly-linked list in the specified winding order
164	        if clockwise == (sum > 0.0) {
165	            for i in 0..len {
166	                last = self.insert_node(self.vertices + i, &points[i], last);
167	            }
168	        } else {
169	            for i in (0..len).rev() {
170	                last = self.insert_node(self.vertices + i, &points[i], last);
171	            }
172	        }
173	
174	        if last != NIL {
175	            let next = self.nodes[last].next;
176	            if self.equals(last, next) {
177	                self.remove_node(last);
178	                last = next;
179	            }
180	        }
181	
182	        self.vertices += len;
183	
184	        last
185	    }
186	
187	    /// Create a node and optionally link it with a previous one (in a circular
188	    /// doubly-linked list).
189	    fn insert_node(&mut self, i: usize, pt: &[f64; 2], last: usize) -> usize {
190	        let p = self.construct(i as u32, pt[0], pt[1]);
191	
192	        if last == NIL {
193	            self.nodes[p].prev = p;
194	            self.nodes[p].next = p;
195	        } else {
196	            let next = self.nodes[last].next;
197	            self.nodes[p].next = next;
198	            self.nodes[p].prev = last;
199	            self.nodes[next].prev = p;
200	            self.nodes[last].next = p;
201	        }
202	
203	        p
204	    }
205	
206	    /// Eliminate colinear or duplicate points. Pass `NIL` for `end` to default it
207	    /// to `start`.
208	    fn filter_points(&mut self, start: usize, end: usize) -> usize {
209	        if start == NIL {
210	            return start;
211	        }
212	        let mut end = if end == NIL { start } else { end };
213	
214	        let mut p = start;
215	        loop {
216	            let again;
217	            let prev = self.nodes[p].prev;
218	            let next = self.nodes[p].next;
219	
220	            if !self.nodes[p].steiner && (self.equals(p, next) || self.area(prev, p, next) == 0.0) {
221	                self.remove_node(p);
222	                p = prev;
223	                end = prev;
224	
225	                if p == self.nodes[p].next {
226	                    break;
227	                }
228	                again = true;
229	            } else {
230	                p = next;
231	                again = false;
232	            }
233	
234	            if !(again || p != end) {
235	                break;
236	            }
237	        }
238	
239	        end
240	    }
241	
242	    /// Main ear slicing loop which triangulates a polygon (given as a linked list).
243	    fn earcut_linked(&mut self, ear: usize, pass: i32) {
244	        let mut ear = ear;
245	        if ear == NIL {
246	            return;
247	        }
248	
249	        // interlink polygon nodes in z-order
250	        if pass == 0 && self.hashing {
251	            self.index_curve(ear);
252	        }
253	
254	        let mut stop = ear;
255	
256	        // iterate through ears, slicing them one by one
257	        while self.nodes[ear].prev != self.nodes[ear].next {
258	            let prev = self.nodes[ear].prev;
259	            let next = self.nodes[ear].next;
260	
261	            let found = if self.hashing {
262	                self.is_ear_hashed(ear)
263	            } else {
264	                self.is_ear(ear)
265	            };
266	
267	            if found {
268	                // cut off the triangle
269	                self.indices.push(self.nodes[prev].i);
270	                self.indices.push(self.nodes[ear].i);
271	                self.indices.push(self.nodes[next].i);
272	
273	                self.remove_node(ear);
274	
275	                // skipping the next vertex leads to less sliver triangles
276	                ear = self.nodes[next].next;
277	                stop = ear;
278	
279	                continue;
280	            }
281	
282	            ear = next;
283	
284	            // if we looped through the whole remaining polygon and can't find any
285	            // more ears
286	            if ear == stop {
287	                if pass == 0 {
288	                    // try filtering points and slicing again
289	                    let filtered = self.filter_points(ear, NIL);
290	                    self.earcut_linked(filtered, 1);
291	                } else if pass == 1 {
292	                    // if this didn't work, try curing all small self-intersections
293	                    // locally
294	                    let filtered = self.filter_points(ear, NIL);
295	                    let cured = self.cure_local_intersections(filtered);
296	                    self.earcut_linked(cured, 2);
297	                } else if pass == 2 {
298	                    // as a last resort, try splitting the remaining polygon into two
299	                    self.split_earcut(ear);
300	                }
301	
302	                break;
303	            }
304	        }
305	    }
306	
307	    /// Check whether a polygon node forms a valid ear with adjacent nodes.
308	    fn is_ear(&self, ear: usize) -> bool {
309	        let a = self.nodes[ear].prev;
310	        let b = ear;
311	        let c = self.nodes[ear].next;
312	
313	        if self.area(a, b, c) >= 0.0 {
314	            return false; // reflex, can't be an ear
315	        }
316	
317	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
318	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
319	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
320	
321	        // now make sure we don't have other points inside the potential ear
322	        let mut p = self.nodes[c].next;
323	
324	        while p != a {
325	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
326	            let (pp, pn) = (self.nodes[p].prev, self.nodes[p].next);
327	            if self.point_in_triangle(ax, ay, bx, by, cx, cy, px, py)
328	                && self.area(pp, p, pn) >= 0.0
329	            {
330	                return false;
331	            }
332	            p = pn;
333	        }
334	
335	        true
336	    }
337	
338	    /// Same as [`Earcut::is_ear`] but only visiting points whose z-order falls in
339	    /// the triangle's bounding box range.
340	    fn is_ear_hashed(&self, ear: usize) -> bool {
341	        let a = self.nodes[ear].prev;
342	        let b = ear;
343	        let c = self.nodes[ear].next;
344	
345	        if self.area(a, b, c) >= 0.0 {
346	            return false; // reflex, can't be an ear
347	        }
348	
349	        let (ax, ay) = (self.nodes[a].x, self.nodes[a].y);
350	        let (bx, by) = (self.nodes[b].x, self.nodes[b].y);
351	        let (cx, cy) = (self.nodes[c].x, self.nodes[c].y);
352	
353	        // triangle bbox; min & max are calculated like this for speed
354	        let min_tx = ax.min(bx.min(cx));
355	        let min_ty = ay.min(by.min(cy));
356	        let max_tx = ax.max(bx.max(cx));
357	        let max_ty = ay.max(by.max(cy));
358	
359	        // z-order range for the current triangle bbox
360	        let min_z = self.z_order(min_tx, min_ty);
