504	    /// Find a bridge between vertices that connects a hole with an outer ring and
505	    /// link it.
506	    fn eliminate_hole(&mut self, hole: usize, outer_node: usize) -> usize {
507	        let bridge = self.find_hole_bridge(hole, outer_node);
508	        if bridge == NIL {
509	            return outer_node;
510	        }
511	
512	        let bridge_reverse = self.split_polygon(bridge, hole);
513	
514	        // filter collinear points around the cuts
515	        let br_next = self.nodes[bridge_reverse].next;
516	        self.filter_points(bridge_reverse, br_next);
517	        let b_next = self.nodes[bridge].next;
518	        self.filter_points(bridge, b_next)
519	    }
