521	    /// David Eberly's algorithm for finding a bridge between a hole and an outer
522	    /// polygon.
523	    fn find_hole_bridge(&self, hole: usize, outer_node: usize) -> usize {
524	        let mut p = outer_node;
525	        let hx = self.nodes[hole].x;
526	        let hy = self.nodes[hole].y;
527	        let mut qx = f64::NEG_INFINITY;
528	        let mut m = NIL;
529	
530	        // find a segment intersected by a ray from the hole's leftmost vertex to
531	        // the left; segment's endpoint with lesser x will be potential connection
532	        // vertex
533	        loop {
534	            let pn = self.nodes[p].next;
535	            let (py, pny) = (self.nodes[p].y, self.nodes[pn].y);
536	            if hy <= py && hy >= pny && pny != py {
537	                let (px, pnx) = (self.nodes[p].x, self.nodes[pn].x);
538	                let x = px + (hy - py) / (pny - py) * (pnx - px);
539	                if x <= hx && x > qx {
540	                    qx = x;
541	                    m = if px < pnx { p } else { pn };
542	                    if x == hx {
543	                        // hole touches outer segment; pick leftmost endpoint
544	                        return m;
545	                    }
546	                }
547	            }
548	            p = pn;
549	            if p == outer_node {
550	                break;
551	            }
552	        }
553	
554	        if m == NIL {
555	            return NIL;
556	        }
557	
558	        // look for points inside the triangle of hole vertex, segment intersection
559	        // and endpoint; if there are no points found, we have a valid connection;
560	        // otherwise choose the vertex of the polygon with the least x
561	        let stop = m;
562	        let mut tan_min = f64::INFINITY;
563	        let mx = self.nodes[m].x;
564	        let my = self.nodes[m].y;
565	
566	        p = m;
567	        loop {
568	            let (px, py) = (self.nodes[p].x, self.nodes[p].y);
569	            if hx >= px
570	                && px >= mx
571	                && hx != px
572	                && self.point_in_triangle(
573	                    if hy < my { hx } else { qx },
574	                    hy,
575	                    mx,
576	                    my,
577	                    if hy < my { qx } else { hx },
578	                    hy,
579	                    px,
580	                    py,
581	                )
582	            {
583	                let tan_cur = (hy - py).abs() / (hx - px); // tangential
584	
585	                if self.locally_inside(p, hole)
586	                    && (tan_cur < tan_min
587	                        || (tan_cur == tan_min
588	                            && (px > self.nodes[m].x || self.sector_contains_sector(m, p))))
589	                {
590	                    m = p;
591	                    tan_min = tan_cur;
592	                }
593	            }
594	
595	            p = self.nodes[p].next;
596	            if p == stop {
597	                break;
598	            }
599	        }
600	
601	        m
602	    }
603	}
